    --bg: #eef2f6;
    --panel: #ffffff;
    --text: #1a2433;
    --muted: #5a6b7f;
    --border: #c9d4e0;
    --error: #b3261e;
    --error-bg: #fdecea;
    --success: #1e6b34;
    --focus: #2e6fb7;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html { -webkit-text-size-adjust: 100%; }
  body {
    font-family: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.5;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
  }
  .service-header {
    background: var(--navy);
    color: #fff;
    width: 100%;
    border-bottom: 4px solid var(--orange);
  }
  .service-header-inner {
    max-width: 1080px;
    margin: 0 auto;
    padding: 1.1rem 1.25rem;
    display: flex;
    align-items: center;
    gap: 0.9rem;
  }
  .service-mark {
    width: 44px; height: 44px;
    flex: 0 0 auto;
    border-radius: 8px;
    background: var(--orange);
    color: var(--navy-dark);
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 1.25rem;
  }
  .service-header h1 { font-size: 1.3rem; font-weight: 700; }
  .service-header p { font-size: 0.85rem; color: #b9c8da; margin-top: 0.1rem; }

  main {
    flex: 1;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    padding: 2.5rem 1rem 3rem;
  }
  .panel {
    background: var(--panel);
    width: 100%;
    max-width: 720px;
    border-radius: 10px;
    box-shadow: 0 6px 24px rgba(11, 31, 58, 0.12);
    border: 1px solid #dde5ee;
    padding: 2rem 2rem 2.25rem;
  }
  .panel h2 { font-size: 1.45rem; color: var(--navy); margin-bottom: 0.35rem; }
  .panel .intro { color: var(--muted); font-size: 0.95rem; margin-bottom: 1.5rem; }

  .form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.1rem 1.25rem;
  }
  .field { display: flex; flex-direction: column; }
  .field.full { grid-column: 1 / -1; }
  label { font-weight: 600; font-size: 0.92rem; margin-bottom: 0.35rem; color: var(--navy); }
  .optional { font-weight: 400; color: var(--muted); font-size: 0.82rem; margin-left: 0.25rem; }
  .hint { font-size: 0.8rem; color: var(--muted); margin-top: 0.3rem; }

  input[type="text"], input[type="email"], input[type="password"], input[type="date"] {
    width: 100%;
    padding: 0.65rem 0.75rem;
    font-size: 1rem;
    border: 1.5px solid var(--border);
    border-radius: 6px;
    background: #fff;
    color: var(--text);
  }
  input:focus-visible, button:focus-visible {
    outline: 3px solid var(--focus);
    outline-offset: 2px;
  }
  input[aria-invalid="true"] { border-color: var(--error); background: #fffafa; }

  .error-msg {
    display: none;
    color: var(--error);
    font-size: 0.82rem;
    margin-top: 0.35rem;
    font-weight: 500;
  }
  .error-msg.visible { display: block; }
  .error-msg.visible::before { content: "⚠ "; }

  .checkbox-wrap {
    display: flex;
    align-items: flex-start;
    gap: 0.6rem;
    cursor: pointer;
    font-weight: 400;
  }
  .checkbox-wrap input {
    width: 1.15rem; height: 1.15rem;
    margin-top: 0.15rem;
    accent-color: var(--orange);
    flex: 0 0 auto;
    cursor: pointer;
  }
  .checkbox-wrap span { font-size: 0.92rem; }

  .pw-toggle-row {
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }
  .toggle-pw {
    border: 1.5px solid var(--navy);
    background: #fff;
    color: var(--navy);
    font-size: 0.88rem;
    font-weight: 600;
    padding: 0.45rem 0.9rem;
    border-radius: 6px;
    cursor: pointer;
  }
  .toggle-pw:hover { background: #eef2f8; }

  .submit-row { grid-column: 1 / -1; margin-top: 0.4rem; }
  button[type="submit"] {
    width: 100%;
    background: var(--orange);
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 0.85rem 1rem;
    font-size: 1.05rem;
    font-weight: 700;
    cursor: pointer;
  }
  button[type="submit"]:hover { background: var(--orange-dark); }

  .status-banner {
    display: none;
    grid-column: 1 / -1;
    border-radius: 6px;
    padding: 0.8rem 1rem;
    font-size: 0.92rem;
    font-weight: 600;
  }
  .status-banner.error { display: block; background: var(--error-bg); color: var(--error); border: 1px solid #f2b8b5; }

  .success-view { text-align: center; padding: 1rem 0; }
  .success-view .tick {
    width: 56px; height: 56px;
    border-radius: 50%;
    background: #e6f4ea;
    color: var(--success);
    display: grid; place-items: center;
    font-size: 1.8rem;
    margin: 0 auto 1rem;
  }
  .success-view p { color: var(--muted); margin: 0.5rem 0 1.25rem; }
  .link-btn {
    background: none; border: none; color: var(--navy);
    text-decoration: underline; cursor: pointer; font-size: 0.95rem;
  }

  footer { text-align: center; color: var(--muted); font-size: 0.8rem; padding: 1rem; }

  @media (max-width: 560px) {
    .form-grid { grid-template-columns: 1fr; }
    .panel { padding: 1.5rem 1.25rem 1.75rem; }
    .service-header h1 { font-size: 1.1rem; }
  }
</style>
</head>
<body>

<header class="service-header">
  <div class="service-header-inner">
    <div class="service-mark" aria-hidden="true">PS</div>
    <div>
      <h1>Public Service Portal</h1>
      <p>Official citizen account registration</p>
    </div>
  </div>
</header>

<main>
  <section class="panel" aria-labelledby="form-heading">
    <div id="form-view">
      <h2 id="form-heading">Create your account</h2>
      <p class="intro">Register for a secure citizen account. Fields marked <span aria-hidden="true">*</span> are required.</p>

      <form id="reg-form" novalidate>
        <div class="form-grid">
          <div id="status-banner" class="status-banner" role="alert" aria-live="assertive"></div>

          <div class="field">
            <label for="username">Username <span aria-hidden="true">*</span></label>
            <input type="text" id="username" name="username" autocomplete="username"
                   required aria-describedby="username-hint username-error">
            <p class="hint" id="username-hint">3–20 characters. Starts with a letter; letters, numbers and underscores only.</p>
            <p class="error-msg" id="username-error"></p>
          </div>

          <div class="field">
            <label for="email">Email address <span aria-hidden="true">*</span></label>
            <input type="email" id="email" name="email" autocomplete="email"
                   required aria-describedby="email-error">
            <p class="error-msg" id="email-error"></p>
          </div>

          <div class="field">
            <label for="dob">Date of birth <span class="optional">(optional)</span></label>
            <input type="date" id="dob" name="dob" autocomplete="bday"
                   aria-describedby="dob-error">
            <p class="error-msg" id="dob-error"></p>
          </div>

          <div class="field">
            <label for="password">Password <span aria-hidden="true">*</span></label>
            <input type="password" id="password" name="password" autocomplete="new-password"
                   required aria-describedby="password-hint password-error">
            <p class="hint" id="password-hint">10–64 characters, with at least one letter and one number.</p>
            <p class="error-msg" id="password-error"></p>
          </div>

          <div class="field">
            <label for="confirm">Confirm password <span aria-hidden="true">*</span></label>
            <input type="password" id="confirm" name="confirm" autocomplete="new-password"
                   required aria-describedby="confirm-error">
            <p class="error-msg" id="confirm-error"></p>
          </div>

          <div class="pw-toggle-row">
            <button type="button" class="toggle-pw" id="toggle-passwords"
                    aria-pressed="false" aria-label="Show passwords">Show passwords</button>
          </div>

          <div class="field full">
            <label class="checkbox-wrap" for="terms">
              <input type="checkbox" id="terms" name="terms" required aria-describedby="terms-error">
              <span>I agree to the Terms of Service and confirm the information provided is accurate. <span aria-hidden="true">*</span></span>
            </label>
            <p class="error-msg" id="terms-error"></p>
          </div>

          <div class="submit-row">
            <button type="submit">Create account</button>
          </div>
        </div>
      </form>
    </div>

    <div id="success-view" class="success-view" hidden role="status" aria-live="polite" tabindex="-1">
      <div class="tick" aria-hidden="true">✓</div>
      <h2>Registration complete</h2>
      <p id="success-msg">Your account has been created successfully.</p>
      <button type="button" class="link-btn" id="register-another">Register another account</button>
    </div>
  </section>
</main>

<footer>Public Service Portal — a demonstration registration service.</footer>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "psp_registrations";
  var form = document.getElementById("reg-form");
  var banner = document.getElementById("status-banner");
  var formView = document.getElementById("form-view");
  var successView = document.getElementById("success-view");
  var successMsg = document.getElementById("success-msg");

  function getRegistrations() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      var data = raw ? JSON.parse(raw) : [];
      return Array.isArray(data) ? data : [];
    } catch (e) { return []; }
  }
  function saveRegistration(entry) {
    try {
      var list = getRegistrations();
      list.push(entry);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
    } catch (e) { }
  }

  var fields = {
    username: document.getElementById("username"),
    email: document.getElementById("email"),
    dob: document.getElementById("dob"),
    password: document.getElementById("password"),
    confirm: document.getElementById("confirm"),
    terms: document.getElementById("terms")
  };

  function setError(name, message) {
    var input = fields[name];
    var err = document.getElementById(name + "-error");
    if (message) {
      err.textContent = message;
      err.classList.add("visible");
      input.setAttribute("aria-invalid", "true");
    } else {
      err.textContent = "";
      err.classList.remove("visible");
      input.removeAttribute("aria-invalid");
    }
  }

  function normUsername(v) { return v.trim(); }
  function normEmail(v) { return v.trim().toLowerCase(); }

  function validateUsername() {
    var v = normUsername(fields.username.value);
    if (!v) return "Username is required.";
    if (v.length < 3) return "Username must be at least 3 characters long.";
    if (v.length > 20) return "Username must be 20 characters or fewer.";
    if (!/^[A-Za-z]/.test(v)) return "Username must start with a letter.";
    if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(v)) return "Username may only contain letters, numbers, and underscores.";
    var dup = getRegistrations().some(function (r) {
      return normUsername(String(r.username)).toLowerCase() === v.toLowerCase();
    });
    if (dup) return "This username is already registered. Please choose another.";
    return "";
  }

  function validateEmail() {
    var v = normEmail(fields.email.value);
    if (!v) return "Email address is required.";
    if (/\s/.test(v)) return "Email address must not contain spaces.";
    var parts = v.split("@");
    if (parts.length !== 2 || !parts[0] || !parts[1]) {
      return "Enter a valid email address, e.g. name@example.com.";
    }
    var local = parts[0], domain = parts[1];
    if (local.indexOf("..") !== -1 || domain.indexOf("..") !== -1) {
      return "Email address must not contain consecutive dots.";
    }
    if (local.charAt(0) === "." || local.charAt(local.length - 1) === ".") {
      return "Email address must not start or end with a dot.";
    }
    var labels = domain.split(".");
    if (labels.length < 2) return "Enter a valid email address, e.g. name@example.com.";
    for (var i = 0; i < labels.length; i++) {
      var lab = labels[i];
      if (!lab) return "Enter a valid email address, e.g. name@example.com.";
      if (lab.charAt(0) === "-" || lab.charAt(lab.length - 1) === "-") {
        return "Email domain labels must not start or end with a hyphen.";
      }
    }
    var dup = getRegistrations().some(function (r) {
      return normEmail(String(r.email)) === v;
    });
    if (dup) return "An account with this email address is already registered.";
    return "";
  }

  function validateDob() {
    var v = fields.dob.value;
    if (!v) return "";
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v);
    if (!m) return "Enter a valid date in the format YYYY-MM-DD.";
    var y = +m[1], mo = +m[2], d = +m[3];
    var dt = new Date(y, mo - 1, d);
    if (dt.getFullYear() !== y || dt.getMonth() !== mo - 1 || dt.getDate() !== d) {
      return "Enter a real calendar date.";
    }
    return "";
  }

  function validatePassword() {
    var v = fields.password.value;
    if (!v) return "Password is required.";
    if (v.length < 10) return "Password must be at least 10 characters long.";
    if (v.length > 64) return "Password must be 64 characters or fewer.";
    if (!/[A-Za-z]/.test(v) || !/[0-9]/.test(v)) {
      return "Password must include at least one letter and one number.";
    }
    return "";
  }

  function validateConfirm() {
    var v = fields.confirm.value;
    if (!v) return "Please confirm your password.";
    if (v !== fields.password.value) return "Passwords do not match.";
    return "";
  }

  function validateTerms() {
    return fields.terms.checked ? "" : "You must accept the Terms of Service to register.";
  }

  var validators = {
    username: validateUsername,
    email: validateEmail,
    dob: validateDob,
    password: validatePassword,
    confirm: validateConfirm,
    terms: validateTerms
  };

  function validateField(name) {
    var msg = validators[name]();
    setError(name, msg);
    return !msg;
  }

  Object.keys(validators).forEach(function (name) {
    var input = fields[name];
    var evt = input.type === "checkbox" ? "change" : "blur";
    input.addEventListener(evt, function () { validateField(name); });
    input.addEventListener("input", function () {
      if (input.getAttribute("aria-invalid") === "true") validateField(name);
      if (name === "password" && fields.confirm.getAttribute("aria-invalid") === "true") {
        validateField("confirm");
      }
    });
  });

  var toggleBtn = document.getElementById("toggle-passwords");
  toggleBtn.addEventListener("click", function () {
    var showing = fields.password.type === "text";
    var next = showing ? "password" : "text";
    fields.password.type = next;
    fields.confirm.type = next;
    toggleBtn.setAttribute("aria-pressed", String(!showing));
    var label = showing ? "Show passwords" : "Hide passwords";
    toggleBtn.textContent = label;
    toggleBtn.setAttribute("aria-label", label);
  });

  function showBanner(message) {
    banner.className = "status-banner error";
    banner.textContent = message;
  }
  function hideBanner() {
    banner.className = "status-banner";
    banner.textContent = "";
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    hideBanner();

    var order = ["username", "email", "dob", "password", "confirm", "terms"];
    var firstInvalid = null;
    order.forEach(function (name) {
      if (!validateField(name) && !firstInvalid) firstInvalid = fields[name];
    });

    if (firstInvalid) {
      showBanner("There is a problem with your registration. Please correct the errors below and try again.");
      firstInvalid.focus();
      return;
    }

    var uname = normUsername(fields.username.value);
    var email = normEmail(fields.email.value);
    saveRegistration({
      username: uname,
      email: email,
      dob: fields.dob.value || null,
      registeredAt: new Date().toISOString()
    });

    successMsg.textContent = "Welcome, " + uname + "! Your account has been created successfully. A confirmation will be sent to " + email + ".";
    formView.hidden = true;
    successView.hidden = false;
    successView.focus();
  });

  document.getElementById("register-another").addEventListener("click", function () {
    form.reset();
    Object.keys(validators).forEach(function (name) { setError(name, ""); });
    fields.password.type = "password";
    fields.confirm.type = "password";
    toggleBtn.setAttribute("aria-pressed", "false");
    toggleBtn.textContent = "Show passwords";
    toggleBtn.setAttribute("aria-label", "Show passwords");
    hideBanner();
    successView.hidden = true;
    formView.hidden = false;
    fields.username.focus();
  });
})();
</script>
</body>
</html>
