<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Register — Public Service Portal</title>
<style>
  :root {
    --navy: #0b1f3a;
    --navy-dark: #071527;
    --orange: #e8701a;
    --orange-dark: #c85e10;
    --bg: #eef2f6;
    --panel: #ffffff;
    --text: #1a2433;
    --muted: #5a6b7f;
    --border: #c9d4e0;
    --error: #b3261e;
    --error-bg: #fdecea;
    --success: #1e6b34;
    --focus: #2e6fb7;
