  }
  .service-header-inner {
    max-width: 1080px;
    margin: 0 auto;
    padding: 1.1rem 1.25rem;
    display: flex;
    align-items: center;
    gap: 0.9rem;
  }
  .service-mark {
    width: 44px; height: 44px;
    flex: 0 0 auto;
    border-radius: 8px;
    background: var(--orange);
    color: var(--navy-dark);
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 1.25rem;
  }
  .service-header h1 { font-size: 1.3rem; font-weight: 700; }
  .service-header p { font-size: 0.85rem; color: #b9c8da; margin-top: 0.1rem; }

  main {
    flex: 1;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    padding: 2.5rem 1rem 3rem;
  }
  .panel {
    background: var(--panel);
    width: 100%;
    max-width: 720px;
    border-radius: 10px;
    box-shadow: 0 6px 24px rgba(11, 31, 58, 0.12);
